def ball_area(p, m):
    """Midpoint estimate of the d_p unit-ball area with m strips."""
    if p < 1:
        raise ValueError("p must be at least 1")
    h = 1 / m
    total = 0.0
    for k in range(m):
        x = (k + 0.5) * h
        total += (1 - x ** p) ** (1 / p)
    return 4 * total * h
